#!/bin/sh
# Régénère les six photos de la page Travailler (mêmes prompts, mêmes graines) en 1536 × 864.
cd "$(dirname "$0")"
Z=../../../../scripts/site-scenes/zimage.py
S="photorealistic interior photograph, late evening, warm lamp light mixed with the cool glow of computer screens, natural skin tones, 35mm photograph, shallow depth of field, soft shadows, realistic, candid moment, no text"
S2="photorealistic interior photograph, late evening, warm lamp light mixed with the cool glow of a computer screen, natural skin tones, 35mm photograph, shallow depth of field, soft shadows, realistic, candid moment, no text"
python3 -I $Z creation "A woman around forty with short dark curly hair, seen from behind and slightly from the side, retouching a colourful portrait photograph on a large wide computer monitor while drawing with a stylus on a black pen tablet on her wooden desk, small creative studio with plants, pinned prints and colour swatches on the wall, a second monitor showing a colour palette, $S" --seed 1
python3 -I $Z deportee "A man in his mid forties with greying hair and glasses, seen from three quarters behind, working on a thin laptop at a kitchen table at home in the evening, the laptop screen shows a detailed 3D architectural model of a modern house in white and wood, a cup of tea and a notebook with sketches beside him, window with city lights behind, $S" --seed 2
python3 -I $Z equipe "A small creative team in a modern studio office in the evening, a woman about thirty-five and two men in their forties gathered around a desk with two large monitors showing a video editing timeline and a colourful film frame, one man pointing at the screen, exposed brick wall, desk lamps, plants, $S" --seed 1
python3 -I $Z jeustudio "In a video game studio at dusk, a woman in her thirties holding a black game controller plays a colourful fantasy adventure game on a large monitor, a man in his forties with a beard stands beside her taking notes on a tablet, shelves with figurines, acoustic panels, $S" --seed 1
python3 -I $Z tablette "A woman around forty with short dark curly hair, seen from three quarters behind, sitting at a wooden desk and drawing a colourful illustration with a stylus on an iPad lying flat on the desk in front of her, her eyes on the tablet, behind the tablet a large computer monitor shows the same colourful illustration in a drawing application, small creative studio with plants and pinned prints on the wall, $S2" --seed 11
python3 -I $Z wacom "A man in his late thirties with a short beard, seen from the side, drawing with a pen on a black graphics tablet on his desk while looking at a large computer monitor that shows a 3D character sculpt, his hand holding the pen on the tablet surface, studio desk with a mechanical keyboard pushed aside, $S2" --seed 21
